const NANDA_DEVI_LOCATIONS=[{name:"Nanda Devi Summit",lat:30.3753,lng:79.867,description:"The main summit at 7,816 m, the highest peak located entirely within India."},{name:"Nanda Devi East",lat:30.3653,lng:79.887,description:"The eastern twin peak at 7,434 m, first climbed in 1939 by a Swiss expedition."},{name:"Nanda Devi Inner Sanctuary",lat:30.38,lng:79.85,description:"A natural amphitheater surrounded by a 7,000 m ring of peaks, once considered unclimbable."},{name:"Rishi Gorge",lat:30.395,lng:79.83,description:"The dramatic gorge carved by the Rishi Ganga River, the only entry into the inner sanctuary."},{name:"Lata Village",lat:30.41,lng:79.79,description:"A traditional Kumaoni village and starting point for treks at 2,100 m."},{name:"Tapovan",lat:30.43,lng:79.76,description:"An alpine meadow at 4,400 m known for hot springs and stunning mountain views."},{name:"Joshimath",lat:30.5563,lng:79.564,description:"A historic town at 1,890 m and gateway to Badrinath, base for Nanda Devi expeditions."}],NANDA_DEVI_GALLERY=[{src:"https://upload.wikimedia.org/wikipedia/commons/d/df/Nanda_devi.jpg",caption:"Nanda Devi (7,816 m) — India's highest peak entirely within its borders and the 23rd highest in the world."},{src:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Nanda_devi.jpg/1280px-Nanda_devi.jpg",caption:"The majestic Nanda Devi summit pyramid as seen from the surrounding Garhwal Himalayas."},{src:"https://upload.wikimedia.org/wikipedia/commons/2/21/Nanda_Devi_Biosphere_Reserve_-_Chamoli.jpg",caption:"Nanda Devi Biosphere Reserve near Trishul peak, on the way to Roopkund, Chamoli district."},{src:"https://upload.wikimedia.org/wikipedia/commons/1/17/Reflection_of_Nanda_Devi_Hills_on_Hemkund_Sahib_Lake_Chamoli%2C_India.jpg",caption:"Reflection of Nanda Devi Hills on Hemkund Sahib Lake, Chamoli — a sacred alpine lake at 4,300 m."},{src:"https://upload.wikimedia.org/wikipedia/commons/2/2e/Rishi_Ganga_gorge_-_Shipton-Tilman_team_climbing_buttress.jpg",caption:"Shipton-Tilman 1934 Nanda Devi Sanctuary expedition — hauling loads in the Rishi Ganga gorge."},{src:"https://upload.wikimedia.org/wikipedia/commons/b/b6/Dhauliganga_and_Rishiganga_Valleys.jpg",caption:"The Dhauliganga and Rishiganga river valleys in the Garhwal Himalayas, Uttarakhand."},{src:"https://upload.wikimedia.org/wikipedia/commons/d/de/Garhwal_Himalayas_Uttarakhand_India.jpg",caption:"Panoramic view of the Garhwal Himalayas in Uttarakhand — home to Nanda Devi and surrounding peaks."}],NANDA_DEVI_FACTS=["Nanda Devi means 'Bliss-Giving Goddess' in Sanskrit. The mountain is revered as the embodiment of Goddess Parvati, consort of Lord Shiva, and is sacred to the people of Kumaon and Garhwal.","The inner sanctuary of Nanda Devi was considered unclimbable for decades because it is surrounded by a nearly impenetrable ring of peaks exceeding 7,000 meters, with only one narrow entry through the Rishi Gorge.","In 1936, Eric Shipton and H.W. Tilman became the first to reach the summit, making Nanda Devi the highest peak climbed at that time (above 7,620 m).","The 1939 German expedition led by Karl Wien vanished in the inner sanctuary. Their remains and equipment were not found until 1959, 20 years later, when glacial recession revealed the wreckage.","Nanda Devi and its surrounding Valley of Flowers were jointly designated a UNESCO World Heritage Site in 1988, recognizing their outstanding natural beauty and biodiversity.","The Nanda Devi Biosphere Reserve spans 6,407 sq km and is home to over 800 plant species, 114 bird species, and rare mammals including snow leopards, Himalayan tahr, and Asiatic black bears.","The 2013 Kedarnath disaster and 2021 Chamoli flood significantly impacted the region, destroying the Rishi Ganga National Park but also revealing the fragility of this mountain ecosystem."],NANDA_DEVI_FAQS=[{question:"Where is Nanda Devi located?",answer:"Nanda Devi is located in the Garhwal Himalayas of Uttarakhand, India, spanning the Chamoli and Pithoragarh districts. It stands at 7,816 meters above sea level."},{question:"How tall is Nanda Devi?",answer:"Nanda Devi stands at an elevation of 7,816 meters (25,643 feet), making it the second-highest mountain in India and the 23rd highest in the world."},{question:"Is Nanda Devi higher than Kanchenjunga?",answer:"No, Nanda Devi (7,816 m) is lower than Kanchenjunga (8,586 m). Nanda Devi is India's second-highest peak, while Kanchenjunga is the highest."},{question:"What is the Nanda Devi Inner Sanctuary?",answer:"The Inner Sanctuary is a natural amphitheater surrounded by a ring of peaks exceeding 7,000 meters, with only one narrow entry through the Rishi Gorge. It was once considered the most formidable mountain fortress in the Himalayas."},{question:"When is the best time to trek near Nanda Devi?",answer:"The best seasons are pre-monsoon (May to June) when alpine wildflowers are in bloom, and post-monsoon (September to October) when skies are clear and views are at their best."},{question:"Do I need a permit to trek in the Nanda Devi area?",answer:"Yes, special permits are required for trekking in the Nanda Devi Biosphere Reserve. The inner sanctuary requires a Forest Department permit, and trekkers must travel with a registered guide."},{question:"Is Nanda Devi a UNESCO World Heritage Site?",answer:"Yes, Nanda Devi and the Valley of Flowers were jointly designated a UNESCO World Heritage Site in 1988, recognized for outstanding natural beauty and exceptional biodiversity."}];let map=null,currentGalleryIndex=0,factIndex=0,factIntervalId=null;function init(){initAccordion(),initGallery(),initFactsRotator(),initMap(),initLightbox(),initScrollReveal(),initParallax()}function initScrollReveal(){const e=document.querySelectorAll(".reveal");if(!e.length)return;const a=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("revealed"),a.unobserve(e.target))})},{threshold:.12,rootMargin:"0px 0px -40px 0px"});e.forEach(e=>a.observe(e))}functi